pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(uint256 amount, address target) public {
        // Restrict amount to be within reasonable bounds and not zero
        amount = bound(amount, 1, type(uint256).max);
        // Ensure target is not the zero address and not the owner to avoid complications with frozen check
        vm.assume(target != address(0));
        vm.assume(target != address(this));

        // Mint tokens to owner so they have something to burn
        c.mintToken(address(this), amount);
        // Also mint tokens to target so totalSupply exceeds owner's balance
        c.mintToken(target, amount);
        uint256 ownerBalanceBefore = c.balanceOf(address(this));
        uint256 totalSupplyBefore = c.totalSupply();
        // Owner burns all their tokens
        c.burn(ownerBalanceBefore);
        uint256 ownerBalanceAfter = c.balanceOf(address(this));
        uint256 totalSupplyAfter = c.totalSupply();

        // Assert: after owner burns their tokens, if total supply decreased (correct behavior),
        // then total supply should be at least as large as the sum of remaining balances.
        // In the buggy version totalSupply does not decrease, so totalSupplyAfter will be strictly greater than the sum of balances,
        // violating that totalSupply is never less than the sum of balances (which should always hold).
        // We assert that totalSupply is not strictly greater than the sum of all remaining balances (i.e., totalSupply <= sum of balances is false, actually we assert the opposite direction?)
        // Correct invariant: totalSupply >= sum of balances always. After burn, totalSupply = sum of balances.
        // Bug: totalSupply > sum of balances. So assert that totalSupply == sum of remaining balances in the reference.
        // Sum of balances = ownerBalanceAfter (0) + c.balanceOf(target) (amount)
        uint256 sumBalances = ownerBalanceAfter + c.balanceOf(target);
        assertTrue(totalSupplyAfter == sumBalances);
    }
}

